            Self::And => Operator::And(Box::new(lhs), Box::new(rhs)),
            Self::Divide => Operator::Divide(Box::new(lhs), Box::new(rhs)),
            Self::Equal => Operator::Equal(Box::new(lhs), Box::new(rhs)),
            Self::Exponentiate => Operator::Exponentiate(Box::new(lhs), Box::new(rhs)),
            Self::GreaterThan => Operator::GreaterThan(Box::new(lhs), Box::new(rhs)),
            Self::GreaterThanOrEqual => Operator::GreaterThanOrEqual(Box::new(lhs), Box::new(rhs)),
            Self::LessThan => Operator::LessThan(Box::new(lhs), Box::new(rhs)),
            Self::LessThanOrEqual => Operator::LessThanOrEqual(Box::new(lhs), Box::new(rhs)),
            Self::Like => Operator::Like(Box::new(lhs), Box::new(rhs)),
            Self::Multiply => Operator::Multiply(Box::new(lhs), Box::new(rhs)),
            Self::NotEqual => Operator::NotEqual(Box::new(lhs), Box::new(rhs)),
            Self::Or => Operator::Or(Box::new(lhs), Box::new(rhs)),
            Self::Remainder => Operator::Remainder(Box::new(lhs), Box::new(rhs)),
            Self::Subtract => Operator::Subtract(Box::new(lhs), Box::new(rhs)),
        }
        .into()
    }
}

/// Postfix operators.
enum PostfixOperator {
    Factorial,           // a!
    Is(ast::Literal),    // a IS NULL | NAN
    IsNot(ast::Literal), // a IS NOT NULL | NAN
}

impl PostfixOperator {
    // The operator precedence.
    fn precedence(&self) -> Precedence {
        70
    }

    /// Builds an AST expression for the operator.
    fn into_expression(self, lhs: ast::Expression) -> ast::Expression {
        use ast::Operator::*;
        match self {
            Self::Factorial => Operator::Factorial(Box::new(lhs)).into(),
            Self::Is(lit) => Operator::Is(Box::new(lhs), lit).into(),
            Self::IsNot(lit) => Operator::Not(Box::new(Operator::Is(Box::new(lhs), lit).into())).into(),
        }
    }
}
