            return match kw {
                Keyword::And => Some(InfixOperator::And),
                Keyword::Or => Some(InfixOperator::Or),
                Keyword::Like => Some(InfixOperator::Like),
                _ => None,
            };
        }

        if self.next_is(Token::Equal) {
            return Some(InfixOperator::Equal);
        }

        if self.next_is(Token::NotEqual) {
            return Some(InfixOperator::NotEqual);
        }

        if self.next_is(Token::GreaterThan) {
